changeSet.sql:
insert into role (name) values ('GLOBAL_EXERCISE_AUTHOR');

insert into role_permission (role_id, permission_id)
select r.id, p.id from role r, permission p
where r.name = 'GLOBAL_EXERCISE_AUTHOR'
  and p.name in ('VIEW_EXERCISE','CREATE_EXERCISE','EDIT_EXERCISE','SOLVE_EXERCISE');

changeSet.rollback:
delete rp from role_permission rp join role r on r.id = rp.role_id
where r.name = 'GLOBAL_EXERCISE_AUTHOR';
delete from role where name = 'GLOBAL_EXERCISE_AUTHOR';

insert into role_permission (role_id, permission_id)
select r.id, p.id from role r, permission p
where r.name = 'STUDENT' and p.name in ('VIEW_COURSE','VIEW_EXERCISE');

changeSet.sql:
insert ignore into role_user_assignment (user_id, role_id, permission_scope_id) select distinct ur.user_id, r.id, ps.id from user_role ur join role r on r.name = 'GLOBAL_ADMIN' join permission_scope ps on ps.kind = 'GLOBAL' where ur.roles = 'ADMIN';
insert ignore into role_user_assignment (user_id, role_id, permission_scope_id) select distinct ur.user_id, r.id, ps.id from user_role ur join role r on r.name = 'GLOBAL_EXERCISE_AUTHOR' join permission_scope ps on ps.kind = 'GLOBAL' where ur.roles = 'TEACHER';
drop table user_role;

changeSet.rollback:
create table user_role (
    user_id bigint not null,
    roles   varchar(255) null,
    constraint fk_user_role_user foreign key (user_id) references user(id)
);
